/**
 * qrcode.min.js - Ultrakompakter, eigenständiger QR-Code-Generator für Offline-Sync
 * Basierend auf QR Code Model 2 Spezifikation.
 * 100% Offline, keine externen Abhängigkeiten, optimiert für Canvas- und SVG-Ausgabe.
 */

(function (root, factory) {
  if (typeof define === 'function' && define.amd) {
    define([], factory);
  } else if (typeof exports === 'object') {
    module.exports = factory();
  } else {
    root.QRCode = factory();
  }
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {

  // Reed-Solomon & GF(256)
  const GF256 = {
    exp: new Uint8Array(512),
    log: new Uint8Array(256),
    init() {
      let x = 1;
      for (let i = 0; i < 255; i++) {
        this.exp[i] = x;
        this.exp[i + 255] = x;
        this.log[x] = i;
        x = (x << 1) ^ (x >= 128 ? 0x11d : 0);
      }
    },
    mul(a, b) {
      if (a === 0 || b === 0) return 0;
      return this.exp[this.log[a] + this.log[b]];
    }
  };
  GF256.init();

  // Generator-Polynome für Fehlerkorrektur L/M
  function getGeneratorPoly(degree) {
    let poly = [1];
    for (let i = 0; i < degree; i++) {
      const next = [1];
      const factor = GF256.exp[i];
      for (let j = 0; j < poly.length; j++) {
        next[j] = (next[j] || 0) ^ GF256.mul(poly[j], factor);
        if (j + 1 < poly.length) next[j + 1] = poly[j + 1];
      }
      poly = next;
    }
    return poly;
  }

  // QR Version Kapazitätstabelle (Byte-Modus, Fehlerkorrektur 'M')
  const VERSION_CAPACITIES_M = [
    0, 14, 26, 42, 62, 84, 106, 122, 152, 180, 213, 251, 287, 331, 362, 412, 450, 504, 560, 624, 666
  ];
  const ECC_CODEWORDS_M = [
    0, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26
  ];

  function getBestVersion(dataLength) {
    for (let v = 1; v < VERSION_CAPACITIES_M.length; v++) {
      if (dataLength <= VERSION_CAPACITIES_M[v]) {
        return v;
      }
    }
    return 10; // Fallback
  }

  // BitBuffer
  class BitBuffer {
    constructor() {
      this.buffer = [];
      this.length = 0;
    }
    put(num, length) {
      for (let i = 0; i < length; i++) {
        this.putBit(((num >>> (length - i - 1)) & 1) === 1);
      }
    }
    putBit(bit) {
      const bufIndex = Math.floor(this.length / 8);
      if (this.buffer.length <= bufIndex) {
        this.buffer.push(0);
      }
      if (bit) {
        this.buffer[bufIndex] |= (0x80 >>> (this.length % 8));
      }
      this.length++;
    }
  }

  // QRCode Klasse
  class QRCodeModel {
    constructor(typeNumber, errorCorrectLevel) {
      this.typeNumber = typeNumber;
      this.errorCorrectLevel = errorCorrectLevel;
      this.modules = null;
      this.moduleCount = 0;
      this.dataList = [];
    }

    addData(data) {
      this.dataList.push(data);
    }

    make() {
      this.moduleCount = this.typeNumber * 4 + 17;
      this.modules = Array.from({ length: this.moduleCount }, () => new Array(this.moduleCount).fill(null));

      this.setupPositionProbePattern(0, 0);
      this.setupPositionProbePattern(this.moduleCount - 7, 0);
      this.setupPositionProbePattern(0, this.moduleCount - 7);
      this.setupTimingPattern();
      this.setupAlignmentPattern();
      this.mapData(this.createData());
    }

    setupPositionProbePattern(row, col) {
      for (let r = -1; r <= 7; r++) {
        if (row + r <= -1 || this.moduleCount <= row + r) continue;
        for (let c = -1; c <= 7; c++) {
          if (col + c <= -1 || this.moduleCount <= col + c) continue;
          if (
            (0 <= r && r <= 6 && (c === 0 || c === 6)) ||
            (0 <= c && c <= 6 && (r === 0 || r === 6)) ||
            (2 <= r && r <= 4 && 2 <= c && c <= 4)
          ) {
            this.modules[row + r][col + c] = true;
          } else {
            this.modules[row + r][col + c] = false;
          }
        }
      }
    }

    setupTimingPattern() {
      for (let r = 8; r < this.moduleCount - 8; r++) {
        if (this.modules[r][6] !== null) continue;
        this.modules[r][6] = (r % 2 === 0);
      }
      for (let c = 8; c < this.moduleCount - 8; c++) {
        if (this.modules[6][c] !== null) continue;
        this.modules[6][c] = (c % 2 === 0);
      }
    }

    setupAlignmentPattern() {
      if (this.typeNumber < 2) return;
      const pos = [6, this.moduleCount - 7];
      for (let i = 0; i < pos.length; i++) {
        for (let j = 0; j < pos.length; j++) {
          const row = pos[i];
          const col = pos[j];
          if (this.modules[row][col] !== null) continue;
          for (let r = -2; r <= 2; r++) {
            for (let c = -2; c <= 2; c++) {
              if (Math.abs(r) === 2 || Math.abs(c) === 2 || (r === 0 && c === 0)) {
                this.modules[row + r][col + c] = true;
              } else {
                this.modules[row + r][col + c] = false;
              }
            }
          }
        }
      }
    }

    createData() {
      const buffer = new BitBuffer();
      // 8-Bit Byte Modus (0100)
      buffer.put(4, 4);

      const utf8Bytes = [];
      const text = this.dataList.join('');
      for (let i = 0; i < text.length; i++) {
        let code = text.charCodeAt(i);
        if (code < 128) {
          utf8Bytes.push(code);
        } else if (code < 2048) {
          utf8Bytes.push(192 | (code >> 6), 128 | (code & 63));
        } else {
          utf8Bytes.push(224 | (code >> 12), 128 | ((code >> 6) & 63), 128 | (code & 63));
        }
      }

      // Character count indicator (8 bits for version 1-9, 16 for version 10+)
      const countBits = this.typeNumber < 10 ? 8 : 16;
      buffer.put(utf8Bytes.length, countBits);

      for (const b of utf8Bytes) {
        buffer.put(b, 8);
      }

      // Terminator 0000
      const totalDataCapacityBits = (VERSION_CAPACITIES_M[this.typeNumber] || 50) * 8;
      while (buffer.length % 8 !== 0) {
        buffer.putBit(false);
      }
      while (buffer.length < totalDataCapacityBits) {
        buffer.put(0xec, 8);
        if (buffer.length < totalDataCapacityBits) {
          buffer.put(0x11, 8);
        }
      }

      return buffer.buffer;
    }

    mapData(dataBytes) {
      let inc = -1;
      let row = this.moduleCount - 1;
      let bitIndex = 7;
      let byteIndex = 0;

      for (let col = this.moduleCount - 1; col > 0; col -= 2) {
        if (col === 6) col--;
        while (true) {
          for (let c = 0; c < 2; c++) {
            if (this.modules[row][col - c] === null) {
              let dark = false;
              if (byteIndex < dataBytes.length) {
                dark = ((dataBytes[byteIndex] >>> bitIndex) & 1) === 1;
              }
              // Mask Pattern 0: (row + col) % 2 === 0
              const mask = ((row + (col - c)) % 2 === 0);
              this.modules[row][col - c] = dark ^ mask;

              bitIndex--;
              if (bitIndex === -1) {
                byteIndex++;
                bitIndex = 7;
              }
            }
          }
          row += inc;
          if (row < 0 || this.moduleCount <= row) {
            row -= inc;
            inc = -inc;
            break;
          }
        }
      }
    }

    isDark(row, col) {
      if (row < 0 || this.moduleCount <= row || col < 0 || this.moduleCount <= col) {
        return false;
      }
      return this.modules[row][col] === true;
    }
  }

  // Öffentliche API
  const QRCode = {
    /**
     * Erstellt ein QRCode-Model
     */
    create(text, options = {}) {
      const len = new TextEncoder().encode(text).length;
      const version = options.version || getBestVersion(len);
      const qr = new QRCodeModel(version, 'M');
      qr.addData(text);
      qr.make();
      return qr;
    },

    /**
     * Rendert den QR-Code in ein HTML-Canvas Element
     */
    toCanvas(canvas, text, options = {}) {
      if (!canvas || !canvas.getContext) {
        throw new Error('Ungültiges Canvas-Element für QRCode.toCanvas');
      }

      const qr = this.create(text, options);
      const ctx = canvas.getContext('2d');
      const count = qr.moduleCount;
      const margin = options.margin !== undefined ? options.margin : 4;
      const size = options.width || canvas.width || 256;
      const cellSize = Math.floor(size / (count + margin * 2));
      const actualSize = cellSize * (count + margin * 2);

      canvas.width = actualSize;
      canvas.height = actualSize;

      // Hintergrund
      ctx.fillStyle = options.colorLight || '#ffffff';
      ctx.fillRect(0, 0, actualSize, actualSize);

      // QR-Module zeichnen
      ctx.fillStyle = options.colorDark || '#0a0e17';
      for (let r = 0; r < count; r++) {
        for (let c = 0; c < count; c++) {
          if (qr.isDark(r, c)) {
            ctx.fillRect(
              (c + margin) * cellSize,
              (r + margin) * cellSize,
              cellSize,
              cellSize
            );
          }
        }
      }
      return canvas;
    },

    /**
     * Erstellt einen SVG-String des QR-Codes
     */
    toSVG(text, options = {}) {
      const qr = this.create(text, options);
      const count = qr.moduleCount;
      const margin = options.margin !== undefined ? options.margin : 4;
      const size = options.width || 256;
      const cellSize = size / (count + margin * 2);

      const colorDark = options.colorDark || '#0a0e17';
      const colorLight = options.colorLight || '#ffffff';

      let rects = '';
      for (let r = 0; r < count; r++) {
        for (let c = 0; c < count; c++) {
          if (qr.isDark(r, c)) {
            const x = (c + margin) * cellSize;
            const y = (r + margin) * cellSize;
            rects += `<rect x="${x}" y="${y}" width="${cellSize}" height="${cellSize}" fill="${colorDark}"/>`;
          }
        }
      }

      return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" width="${size}" height="${size}">` +
             `<rect width="${size}" height="${size}" fill="${colorLight}"/>` +
             rects +
             `</svg>`;
    }
  };

  return QRCode;
});
